export function createReadinessPoller(
  refresh: () => void,
  intervalMs = 10_000,
): ReadinessPoller {
  let timer: ReturnType<typeof setInterval> | null = null;
  return {
    sync(notReady: boolean): void {
      if (notReady && timer === null) {
        timer = setInterval(refresh, intervalMs);
      } else if (!notReady && timer !== null) {
        clearInterval(timer);
        timer = null;
      }
    },
    stop(): void {
      if (timer !== null) {
        clearInterval(timer);
        timer = null;
      }
    },
  };
}

